 static GameModel Scanner(double time,string item){var m=new GameModel();m.S.Minutes=time;m.S.X=26.5;m.S.Y=10.01;if(item!=null)m.S.Inventory.Add(item);m.Tick(.02,0,-1,false);return m;}
 static void SecurityChecks(){
  Check(GameModel.IsContraband("pilă")&&GameModel.IsContraband("sârmă")&&GameModel.IsContraband("clește")&&GameModel.IsContraband("lopată")&&!GameModel.IsContraband("bandă")&&!GameModel.IsContraband("biscuiți"),"contraband classification excludes legal supplies");
  var m=Scanner(539.8,"pilă");Check(m.S.Heat>34,"file triggers detector before permit");
  m=Scanner(540,"pilă");Check(m.S.Heat==0,"file permitted at 09:00");m=Scanner(719.9,"sârmă");Check(m.S.Heat==0,"wire permitted before noon");m=Scanner(720,"sârmă");Check(m.S.Heat>34,"wire triggers at noon");
  m=Scanner(550,"clește");Check(m.S.Heat>34,"crafted cutter never exempt");m=Scanner(550,"lopată");Check(m.S.Heat>34,"shovel never exempt");m=Scanner(750,"bandă");Check(m.S.Heat==0,"legal supplies do not alarm");
  m=Scanner(750,"pilă");double heat=m.S.Heat;m.Tick(.02,0,0,false);Check(m.S.Heat<heat,"standing on detector does not repeat alarm");m.Tick(.05,0,1,false);m.Tick(.05,0,-1,false);Check(m.S.Heat>69,"leaving and reentering detector triggers new alarm");
  m=Scanner(750,null);m.S.Inventory.Add("pilă");m.S.Y=10.01;m.S.Heat=30;m.Guards[0].X=26.5;m.Guards[0].Y=11.5;m.Guards[0].DX=0;m.Guards[0].DY=-1;m.Tick(.02,0,-1,false);Check(m.Guards[0].Alert>0,"observed detector alarm reaching 60 triggers pursuit");
  m.Reset();m.S.X=17.5;m.S.Y=12.5;m.S.Minutes=1079.98;m.ToggleWait();m.Advance(.02,0,0,false);Check(!m.Waiting&&m.S.InspectionNoticeDay==1&&m.Message.Contains("18:30"),"18:00 announcement stops waiting");
  m.S.Crates[0].Items.AddRange(new[]{"sârmă","clește"});m.S.Stash.Add("pilă");m.S.Inventory.Add("lopată");m.S.Minutes=1109.98;m.ToggleWait();m.Advance(.02,0,0,false);
  Check(!m.Waiting&&m.S.InspectionDay==1&&m.S.LastInspectionCount==2&&m.S.Evidence[1]==1&&m.S.Evidence[2]==1,"18:30 inspection moves forbidden desk items and stops waiting");
  Check(m.S.Stash.SequenceEqual(new[]{"pilă"})&&m.S.Inventory.SequenceEqual(new[]{"lopată"})&&m.S.Crates[0].Items.SequenceEqual(new[]{"bandă","biscuiți"}),"inspection preserves hidden pocket and legal desk items");Check(m.S.Heat>19&&m.S.Heat<=20,"inspection adds twenty suspicion");
  string save=Path.Combine(output,"security-save.xml");m.Save(save);var loaded=new GameModel();Check(loaded.Load(save)&&loaded.S.Evidence.SequenceEqual(m.S.Evidence)&&loaded.S.InspectionDay==1,"evidence and inspection markers persist");loaded.S.Crates[0].Items.Add("pilă");loaded.S.Minutes=1109.98;loaded.Tick(.02,0,0,false);Check(loaded.S.Crates[0].Items.Contains("pilă")&&loaded.S.Evidence[0]==0,"reload cannot repeat same day inspection");
  loaded.S.Day=2;loaded.S.Minutes=1109.98;loaded.Tick(.02,0,0,false);Check(loaded.S.InspectionDay==2&&loaded.S.Evidence[0]==1,"inspection repeats on later day");
  m.S.X=28.5;m.S.Y=15.5;m.S.Minutes=750;m.S.Heat=0;m.S.Money=5;Check(m.BeginEvidence()&&!m.RecoverEvidence(1)&&m.S.Money==5&&m.S.Evidence[1]==1,"insufficient recovery funds leave evidence intact");m.S.Money=30;m.S.Inventory=Enumerable.Repeat("bandă",6).ToList();Check(!m.RecoverEvidence(1)&&m.S.Money==30&&m.S.Evidence[1]==1,"full pockets cannot spend recovery funds");m.S.Inventory.Clear();Check(m.RecoverEvidence(1)&&m.S.Money==24&&m.S.Evidence[1]==0&&m.S.Inventory.SequenceEqual(new[]{"sârmă"}),"recovery transfers exactly one item and charges price");Check(!m.RecoverEvidence(1)&&!m.RecoverEvidence(-1)&&!m.RecoverEvidence(4)&&m.S.Money==24,"empty or invalid evidence selection cannot duplicate items");
  m.S.Minutes=719.99;Check(!m.CanRecover(),"recovery closed before noon");m.S.Minutes=720;Check(m.CanRecover(),"recovery opens at noon");m.S.Minutes=1319.99;Check(m.CanRecover(),"recovery open before lights out");m.S.Minutes=1320;Check(!m.RecoverEvidence(2),"recovery closes exactly at 22:00");m.S.Minutes=750;m.S.Heat=60;Check(!m.RecoverEvidence(2),"high suspicion blocks recovery");m.S.Heat=0;m.Guards[0].Alert=1;Check(!m.RecoverEvidence(2),"pursuit blocks recovery");m.Guards[0].Alert=0;m.S.X=5.5;Check(!m.RecoverEvidence(2),"stale recovery menu cannot transfer remotely");m.S.X=27.5;m.Tiles[28,15]=2;Check(!m.CanRecover(),"obstruction blocks recovery");m.Build();m.Action="Studiu";Check(!m.CanRecover(),"action blocks recovery");m.Action="";m.S.Won=true;Check(!m.CanRecover(),"victory blocks recovery");m.S.Won=false;m.S.Health=0;Check(!m.CanRecover(),"defeat blocks recovery");
  m.Reset();m.S.Inventory.AddRange(new[]{"clește","bandă"});m.S.Crates[0].Items.Add("sârmă");m.S.Stash.Add("lopată");m.Caught();Check(m.S.Evidence[2]==1&&m.S.Evidence[1]==1&&m.S.Inventory.Count==0&&m.S.Stash.Contains("lopată"),"capture moves pocket and desk contraband while preserving stash");m.Caught();Check(m.S.Evidence.Sum()==2,"repeated capture cannot duplicate original confiscated items");
  m.S.Evidence[0]=-1;m.Save(save);Check(!loaded.Load(save),"negative evidence rejected");m.S.Evidence=new[]{1,2};m.Save(save);Check(!loaded.Load(save),"wrong evidence array length rejected");m.S.Evidence=new[]{1000001,0,0,0};m.Save(save);Check(!loaded.Load(save),"out of range evidence rejected");m.S.Evidence=new int[4];m.S.InspectionDay=2;m.Save(save);Check(!loaded.Load(save),"future inspection day rejected");m.S.InspectionDay=0;m.S.LastInspectionCount=101;m.Save(save);Check(!loaded.Load(save),"invalid last inspection count rejected");m.Reset();Check(m.S.Evidence.Sum()==0&&m.S.InspectionDay==0&&!m.EvidenceOpen,"new game resets security state");
  m.S.Evidence=null;m.Save(save);Check(!loaded.Load(save),"missing evidence state rejected in v5");m.Reset();m.S.InspectionNoticeDay=2;m.Save(save);Check(!loaded.Load(save),"future announcement marker rejected");
  m.Reset();m.S.Evidence[0]=1000000;m.S.Inventory.Add("pilă");m.S.Crates[0].Items.Add("pilă");m.Caught();Check(m.S.Inventory.Contains("pilă")&&m.S.Crates[0].Items.Contains("pilă")&&m.S.Evidence[0]==1000000,"full evidence counter preserves overflow items on capture");m.Save(save);Check(loaded.Load(save),"capacity edge remains a valid save");
  m.Reset();m.S.X=17.5;m.S.Y=12.5;m.S.Minutes=1109.98;m.S.Crates[0].Items.Add("sârmă");m.Save(save);loaded.Load(save);loaded.Tick(.02,0,0,false);Check(loaded.S.Evidence[1]==1&&loaded.S.InspectionDay==1,"load immediately before inspection processes event once");loaded.Save(save);loaded.Load(save);loaded.Tick(.02,0,0,false);Check(loaded.S.Evidence[1]==1,"load immediately after inspection never duplicates evidence");
  m.Reset();m.S.Minutes=1439.98;m.S.InspectionDay=1;m.S.InspectionNoticeDay=1;m.S.Evidence[0]=2;m.Tick(.02,0,0,false);Check(m.S.Day==2&&m.S.Evidence[0]==2&&m.InspectionStatus.Contains("Azi, 18:30"),"midnight retains evidence and schedules next inspection");
  string fixture=Path.GetFullPath(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"..","fixtures","save-v4.xml"));Check(m.Load(fixture)&&m.S.Version==5&&m.S.Money==19&&m.S.TunnelStage==2&&m.S.Inventory.Contains("lopată")&&m.S.Stash.SequenceEqual(new[]{"pilă","sârmă"})&&m.S.Evidence.Sum()==0,"genuine v4 import preserves inventory stash tunnel and economy");m.Tick(.02,0,0,false);Check(m.S.InspectionDay==0&&m.S.Crates[0].Items.Contains("clește"),"late old save import does not retroactively search desk");m.Save(save);Check(loaded.Load(save)&&loaded.S.Stash.Count==2,"imported v4 save round trips as v5");
  m.Reset();m.S.X=28.5;m.S.Y=15.5;m.S.Minutes=1170;m.S.Money=30;m.S.Evidence=new[]{1,1,2,1};m.BeginEvidence();Shot(m,"evidence-stocked","evidence");Shot(m,"security-overview","security");
  GameModel win=null;int winningDelay=-1;for(int delay=0;delay<=90;delay+=3){try{var trial=SecurityCampaign(delay);if(trial!=null&&trial.S.Won){win=trial;winningDelay=delay;break;}}catch(Exception ex){if(ex.Message!="Caught while walking")throw;}}
  Check(win!=null&&win.S.Caught==0,"natural security campaign hides file loses wire recovers it and escapes");Check(win.S.Money==6&&win.S.WorkDone==1&&win.S.LastInspectionCount==1&&win.S.Evidence.Sum()==0,"natural security campaign conserves work payment evidence and recovery costs");Console.WriteLine("Security campaign: delay "+winningDelay+" s; escaped day "+win.S.Day+" "+win.Clock+"; cash "+win.S.Money+"; captures "+win.S.Caught+".");
 }
 static GameModel SecurityCampaign(int delay){
  var m=new GameModel();Walk(m,5.5,5.5);Loot(m);Loot(m);Walk(m,17.5,12.5);UntilRoutine(m);Walk(m,26.5,19.5);UntilRoutine(m);
  Walk(m,24.5,6.5);m.Interact();Wait(m,6.1);Walk(m,25.5,5.5);Loot(m);Loot(m);
  Walk(m,5.5,5.5);m.Interact();m.ToggleStorage();if(!m.DepositStored(m.S.Inventory.IndexOf("pilă")))throw new Exception("Natural file stash failed");m.ToggleStorage();if(!m.DepositStored(m.S.Inventory.IndexOf("sârmă")))throw new Exception("Natural wire deposit failed");m.StorageCrate=-1;
  Walk(m,6.5,19.5);m.Interact();Wait(m,3.1);UntilRoutine(m);UntilRoutine(m);Walk(m,17.5,12.5);UntilRoutine(m);
  if(m.S.Evidence[1]!=1||m.S.Stash.Count!=1)throw new Exception("Natural inspection not observed");Walk(m,28.5,15.5);m.Interact();if(!m.RecoverEvidence(1))throw new Exception("Natural recovery failed");m.EvidenceOpen=false;
  Walk(m,5.5,5.5);m.Interact();m.ToggleStorage();if(!m.TakeStored(0))throw new Exception("Natural stash retrieval failed");m.StorageCrate=-1;m.HiddenStorage=false;if(!m.Craft())throw new Exception("Natural security crafting failed");
  Walk(m,31.5,7.5);Wait(m,delay);Walk(m,31.5,12.5);m.Interact();Wait(m,8.1);if(m.S.Caught>0||!m.S.FenceOpen)return null;Walk(m,33.5,12.5);return m;
 }
